declare b public.agent_runtime_bindings; j public.agent_jobs; t public.tarefas; e public.agent_job_events; k text; reason text; req jsonb; res jsonb; begin if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>16384 then raise exception 'Payload invalido' using errcode='22023'; end if; select * into b from public.agent_runtime_bindings where profile_slug=p_profile_slug for share; if not found or b.status<>'ACTIVE' or b.provider<>'HERMES' or b.agent_id not in ('AGT-01','AGT-04') or not (b.scope_type='BUSINESS' or (b.scope_type='GROUP' and b.agent_id='AGT-01')) then raise exception 'Somente Helena ou Marina ativa resolve bloqueios' using errcode='42501'; end if; k:=nullif(btrim(p_payload->>'idempotency_key'),''); reason:=nullif(btrim(p_payload->>'reason'),''); if k is null or length(k)>120 or reason is null or length(reason)>4000 then raise exception 'Chave e motivo obrigatorios' using errcode='22023'; end if; req:=jsonb_build_object('profile',p_profile_slug,'action','resolve_job_block','payload',p_payload); perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_profile_slug||':'||k,0)); select * into j from public.agent_jobs where job_id=p_payload->>'job_id' for update; if not found or j.business_id is null or j.task_id is null then raise exception 'Job exige tarefa e empresa' using errcode='22023'; end if; if b.scope_type='BUSINESS' and b.business_id is distinct from j.business_id then raise exception 'Empresa fora do escopo' using errcode='42501'; end if; select * into e from public.agent_job_events where job_id=j.job_id and payload->>'workflow_key'=k and event_type like 'WORKFLOW_%'; if e.event_id is not null then if e.payload->'request' is distinct from req then raise exception 'Chave reutilizada com conteudo diferente' using errcode='22023'; end if; return e.payload->'response'; end if; select * into t from public.tarefas where task_id=j.task_id for update; if not found or t.business_id is distinct from j.business_id then raise exception 'Tarefa divergente' using errcode='22023'; end if; if (p_payload->>'expected_task_version')::bigint is distinct from t.row_version then raise exception 'CONFLITO_DE_VERSAO' using errcode='40001'; end if; if j.status<>'WAITING_HELENA' or j.result_payload->>'review_pending'='true' or nullif(btrim(j.result_payload->>'decisao_necessaria'),'') is null then raise exception 'Exige bloqueio por decisao; entrega submetida exige review_delivery' using errcode='22023'; end if; if coalesce(j.attempt_count,0)>=least(coalesce(j.max_attempts,2),2) then raise exception 'Limite de tentativas atingido; replanejar' using errcode='22023'; end if; update public.agent_jobs set status='DRAFT',approval_status='PENDING',updated_at=clock_timestamp(), result_payload=coalesce(result_payload,'{}'::jsonb)||jsonb_build_object('block_resolved_by',b.agent_id,'block_resolution',reason,'block_resolved_at',clock_timestamp()) where job_id=j.job_id; perform public.helena_write_record('tarefas',t.task_id,t.row_version,jsonb_build_object('status','NÃO INICIADA','bloqueio','Bloqueio resolvido; aguardando liberacao da coordenacao')); res:=jsonb_build_object('success',true,'job_id',j.job_id,'status','DRAFT','started',false,'completed',false,'attempt_count',j.attempt_count); insert into public.agent_job_events(job_id,agent_id,business_id,event_type,status,message,payload,correlation_id) values(j.job_id,b.agent_id,j.business_id,'WORKFLOW_resolve_job_block','DRAFT',reason,jsonb_build_object('workflow_key',k,'request',req,'response',res,'profile_slug',p_profile_slug),j.correlation_id); return res; end;